@font-face{font-family:"Bricolage Grotesque";src:url("assets/fonts/BricolageGrotesque.ttf") format("truetype");font-weight:200 800;font-stretch:75% 100%;font-style:normal;font-display:swap}
@font-face{font-family:"Instrument Sans";src:url("assets/fonts/InstrumentSans.ttf") format("truetype");font-weight:400 700;font-stretch:75% 100%;font-style:normal;font-display:swap}
:root{--bg: #EDEEF0;--surface: #FFFFFF;--surface-2: #F5F6F7;--border: #D8DADF;--border-strong:#B3B6BF;--text: #12131A;--text-2: #565862;--text-3: #8A8D97;--accent: #12131A;--on-accent: #FFFFFF;--accent-text: #12131A;--accent-bg: rgba(18,19,26,.1);--dock-bg: #12131A;--dock-fg: #EDEEF0;--success: #178A57;--danger: #D63A3A;--orange: #B8480C;--ink-1: #8EA2FF;--ink-2: #C79BFF;--ink-3: #FFD23F;--ink-4: #52E0A1;--ink-5: #FF8A4C;--ink-6: #2EC4B6;--ink-7: #52C7F2;--ink-8: #FF7EB0;--ink-9: #C3E34A;--ink-text: #12131A;--r-lg: 24px;--r-md: 16px;--r-sm: 12px;--radius: var(--r-lg);--radius-sm: var(--r-md);--radius-xs: var(--r-sm);--f-display: "Bricolage Grotesque", "Arial Narrow", system-ui, sans-serif;--f-body: "Instrument Sans", system-ui, -apple-system, "Segoe UI", sans-serif;--dock-h: 64px;--safe-b: env(safe-area-inset-bottom, 0px);--shadow-md: 0 10px 30px rgba(18,19,26,.22)}
[data-theme=dark]{--bg: #0E0F13;--surface: #181A21;--surface-2: #20222B;--border: #2B2E39;--border-strong:#464A59;--text: #F0EFEA;--text-2: #A3A6B2;--text-3: #70737F;--accent: #F0EFEA;--on-accent: #0E0F13;--accent-text: #F0EFEA;--accent-bg: rgba(240,239,234,.12);--dock-bg: #F0EFEA;--dock-fg: #0E0F13;--success: #4ADE99;--danger: #FF7A7A;--orange: #FF9A5C;--shadow-md: 0 10px 30px rgba(0,0,0,.5)}
*,*:before,*:after{box-sizing:border-box;margin:0;padding:0}
html{height:100%;-webkit-tap-highlight-color:transparent}
body{font-family:var(--f-body);font-size:.9375rem;background:var(--bg);color:var(--text);min-height:100%;line-height:1.5;overscroll-behavior:none;-webkit-font-smoothing:antialiased}
