input{font-family:inherit}
svg{display:block}
.hidden{display:none}
:focus-visible{outline:3px solid var(--text);outline-offset:2px;border-radius:6px}
::-webkit-scrollbar{width:0}
canvas{display:block;width:100%!important}
.app{max-width:430px;margin:0 auto;min-height:100dvh;position:relative;background:var(--bg)}
@media(min-width:600px){body{background:var(--surface-2)}.app{box-shadow:0 0 0 1.5px var(--border)}}
.page{display:flex;flex-direction:column;min-height:100dvh;padding-bottom:calc(var(--dock-h) + var(--safe-b) + 56px)}
.page.hidden{display:none}
.page-header{--logo-h:44px;--logo-m:16px;position:sticky;top:0;z-index:40;display:flex;align-items:center;justify-content:space-between;gap:16px;height:calc(var(--logo-h) + 2*var(--logo-m) + env(safe-area-inset-top,0px));min-height:calc(var(--logo-h) + 2*var(--logo-m) + env(safe-area-inset-top,0px));max-height:calc(var(--logo-h) + 2*var(--logo-m) + env(safe-area-inset-top,0px));padding:env(safe-area-inset-top,0px) 20px 0;background:color-mix(in srgb,var(--bg) 88%,transparent);-webkit-backdrop-filter:blur(14px);backdrop-filter:blur(14px)}
.page-header>:last-child{flex:0 0 auto;margin-left:auto}
.header-logo{display:block;flex:0 1 auto;min-width:0;width:auto;height:var(--logo-h);max-height:var(--logo-h);color:var(--text);overflow:visible}
.header-action-btn{width:44px;height:44px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:var(--surface);border:1.5px solid var(--border-strong);color:var(--text);transition:background .15s}
.header-action-btn:hover{background:var(--surface-2)}
.today-hero{padding:6px 20px 20px}
.hero-date{font-size:.9rem;font-weight:500;color:var(--text-2)}
.hero-score{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-top:2px}
.hero-count{font-family:var(--f-display);font-stretch:75%;font-weight:800;font-size:clamp(5.5rem,31vw,8.5rem);line-height:.84;letter-spacing:-.04em;color:var(--text);display:flex;align-items:baseline}
.hero-count small{font-size:.36em;letter-spacing:-.02em;color:var(--text-2);margin-left:.08em}
.hero-side{text-align:right;padding-bottom:6px}
.hero-caption{font-family:var(--f-display);font-stretch:85%;font-weight:700;font-size:1.15rem;line-height:1.15}
.hero-level{font-size:.82rem;color:var(--text-2);margin-top:2px}
.ink-strip{display:flex;gap:5px;margin-top:18px}
.ink-seg{flex:1;height:16px;border-radius:8px;border:2px solid var(--ink, var(--border-strong));background:transparent;transition:background-color .3s}
.tabs-row{display:flex;gap:24px;padding:0 20px;margin:0 0 16px;border-bottom:1.5px solid var(--border)}
.tab-btn{position:relative;min-height:44px;padding:10px 0 12px;font-family:var(--f-display);font-stretch:85%;font-weight:700;font-size:1.1rem;letter-spacing:-.01em;color:var(--text-2)}
.tab-btn.active{color:var(--text)}
.tab-btn.active:after{content:"";position:absolute;left:0;right:0;bottom:-1.5px;height:4px;border-radius:2px;background:var(--text)}
.tab-panel{padding:0 16px}
.tab-panel.hidden{display:none}
.habits-list{display:flex;flex-direction:column;gap:10px}
