.habit-card-left{display:flex;align-items:center;gap:12px;min-width:0}
.habit-card-emoji,.today-emoji-box,.my-habit-emoji{width:44px;height:44px;border-radius:14px;display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:1.25rem;background:var(--ink, var(--text));color:var(--ink-text);transition:background-color .25s,color .25s}
.habit-card-emoji svg,.today-emoji-box svg,.my-habit-emoji svg{width:22px;height:22px}
.habit-card-name,.today-card-name,.my-habit-name{font-family:var(--f-display);font-stretch:85%;font-weight:700;font-size:1.2rem;line-height:1.15;letter-spacing:-.01em;color:var(--text)}
.habit-card-freq{font-size:.8rem;color:var(--text-2)}
.streak-pill{flex-shrink:0;font-size:.8rem;font-weight:700;color:var(--orange);background:var(--surface-2);padding:4px 10px;border-radius:20px}
.today-card{display:flex;flex-direction:column;gap:12px}
.today-card-top{display:flex;align-items:center;justify-content:space-between;gap:12px}
.today-card-left{display:flex;align-items:center;gap:12px;flex:1;min-width:0}
.today-card-info{min-width:0}
.today-card-name{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.today-card-sub{font-size:.8rem;color:var(--text-2);margin-top:2px}
.today-card-sub.done-flourish{font-family:var(--f-body);font-weight:600;font-size:.8rem;line-height:1.3}
.today-card.done{background:var(--ink);border-color:var(--ink);color:var(--ink-text)}
.today-card.done .today-card-name,.today-card.done .today-card-sub,.today-card.done .ctl-value,.today-card.done .ctl-value small,.today-card.done .ctl-hint{color:var(--ink-text)}
.today-card.done .today-card-sub{opacity:.78}
.today-card.done .today-emoji-box{background:var(--ink-text);color:var(--ink)}
.habit-toggle-btn{width:52px;height:52px;border-radius:50%;border:2.5px solid var(--text);display:flex;align-items:center;justify-content:center;flex-shrink:0;color:transparent;background:transparent;transition:background-color .2s,border-color .2s,color .2s}
.habit-toggle-btn svg{width:24px;height:24px;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}
.habit-toggle-btn .check-icon{display:none}
.habit-toggle-btn.done{background:var(--text);border-color:var(--text);color:var(--bg)}
.habit-toggle-btn.done .check-icon{display:block}
.habit-toggle-btn.fail{background:var(--danger);border-color:var(--danger);color:#fff}
.today-card.done .habit-toggle-btn{border-color:var(--ink-text)}
.today-card.done .habit-toggle-btn.done{background:var(--ink-text);color:var(--ink)}
.pbar{height:14px;background:var(--accent-bg);border-radius:7px;overflow:hidden;margin-bottom:4px}
