.pbar-fill{height:100%;border-radius:7px;background:var(--ink, var(--accent));transition:width .3s ease}
.today-card.done .pbar-fill{background:var(--ink-text)}
.step-btns{display:flex;gap:8px;margin-top:10px}
.step-btn{flex:1;height:46px;border-radius:14px;border:2px solid var(--text);font-family:var(--f-display);font-stretch:85%;font-weight:700;font-size:1.02rem;color:var(--text);transition:background-color .15s,color .15s}
.step-btn:hover{background:var(--text);color:var(--bg)}
.today-card.done .step-btn{border-color:var(--ink-text);color:var(--ink-text)}
.today-card.done .step-btn:hover{background:var(--ink-text);color:var(--ink)}
.week-day-row{display:grid;grid-template-columns:repeat(7,1fr);gap:4px}
.week-day-cell{display:flex;flex-direction:column;align-items:center;gap:6px}
.week-day-label{font-size:.74rem;font-weight:600;color:var(--text-2)}
.week-day-label.today-label,.week-day-label.sunday-label{color:var(--text)}
.week-day-label.today-label{font-weight:800;text-decoration:underline;text-decoration-thickness:2px;text-underline-offset:3px}
.week-day-dot{width:38px;height:38px;border-radius:50%;border:2px solid var(--border);display:flex;align-items:center;justify-content:center;cursor:pointer;transition:background-color .2s,border-color .2s}
