'use strict';
/**
 * Contrôle d'accessibilité statique : chaque <Pressable> déclare un `accessibilityRole`,
 * chaque <TextInput> un `accessibilityLabel`, et aucun texte d'icône seul n'est un bouton muet.
 * Usage : node scripts/check-a11y.cjs
 */
const fs = require('node:fs');
const path = require('node:path');

const walk = (d) => fs.readdirSync(d, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? walk(path.join(d, e.name)) : [path.join(d, e.name)]));
const files = walk(path.join(__dirname, '..', 'src')).filter((f) => f.endsWith('.tsx'));
const problems = [];

for (const f of files) {
  const text = fs.readFileSync(f, 'utf8');
  const rel = path.relative(path.join(__dirname, '..'), f);
  for (const tag of ['Pressable', 'TextInput']) {
    const re = new RegExp(`<${tag}\\b`, 'g');
    let m;
    while ((m = re.exec(text))) {
      // L'ouverture de la balise s'arrête au premier « > » hors accolades.
      let depth = 0;
      let i = m.index + m[0].length;
      for (; i < text.length; i++) {
        const c = text[i];
        if (c === '{') depth++;
        else if (c === '}') depth--;
        else if (c === '>' && depth === 0 && text[i - 1] !== '=') break;
      }
      const open = text.slice(m.index, i);
      const line = text.slice(0, m.index).split('\n').length;
      if (tag === 'Pressable' && !/accessibilityRole=/.test(open)) problems.push(`${rel}:${line} <Pressable> sans accessibilityRole`);
      if (tag === 'TextInput' && !/accessibilityLabel=/.test(open)) problems.push(`${rel}:${line} <TextInput> sans accessibilityLabel`);
      if (tag === 'Pressable' && /accessibilityRole="button"/.test(open) && !/accessibilityLabel=/.test(open)) {
        const body = text.slice(i, text.indexOf('</Pressable>', i));
        if (!/<AppText|<Text|\{[a-z.]*label|\{.*\}\s*<\/|[A-Za-zÀ-ÿ]{3,}/.test(body.replace(/<Icon[^>]*\/>/g, ''))) problems.push(`${rel}:${line} bouton sans texte ni accessibilityLabel`);
      }
    }
  }
}
console.log(`${files.length} fichiers .tsx contrôlés.`);
if (problems.length) {
  console.error('\n' + problems.map((p) => ' - ' + p).join('\n'));
  process.exit(1);
}
console.log('Accessibilité : aucun élément interactif sans rôle ni étiquette.');

text.scripts/check-ui.cjs:
'use strict';
/**
 * Contrôles statiques de la couche UI (src/app, components, theme, services, hooks…)
 * quand React Native n'est pas installé : syntaxe, imports, symboles du domaine et
 * noms d'icônes. Ne remplace PAS `npm run typecheck`, qui reste la vraie vérification.
 *
 * Usage : node scripts/check-ui.cjs   (après `npm test`, qui compile le domaine dans .build)
 */
const fs = require('node:fs');
const path = require('node:path');
const { execFileSync } = require('node:child_process');

const root = path.join(__dirname, '..');
const walk = (dir) =>
  fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
    const p = path.join(dir, e.name);
    return e.isDirectory() ? walk(p) : [p];
  });
const isSource = (f) => /\.(ts|tsx)$/.test(f);
const all = walk(path.join(root, 'src')).filter(isSource);
const pureDirs = ['src/domain', 'src/state/'];
const ui = all.filter((f) => {
  const rel = path.relative(root, f).split(path.sep).join('/');
  return !(rel.startsWith('src/domain') || /^src\/state\/[^/]+\.ts$/.test(rel));
});
const problems = [];

// 1. Syntaxe (tsc doit être dans le PATH : c'est le cas via `npm run check:ui`)
try {
  execFileSync(
    'tsc',
    ['--ignoreConfig', '--noEmit', '--jsx', 'preserve', '--noResolve', '--skipLibCheck', '--target', 'es2022', '--module', 'esnext', ...ui],
    { stdio: 'pipe' },
  );
} catch (e) {
  if (e.code === 'ENOENT') {
    problems.push('syntaxe : « tsc » introuvable (installe typescript et lance `npm run check:ui`)');
  } else {
    for (const line of String(e.stdout || '').split('\n')) if (/error TS(1|5)\d{3}/.test(line)) problems.push(`syntaxe : ${line}`);
  }
}

// 2. Symboles exportés par le domaine et l'état
const exportsOf = (dir) => {
  const names = new Set();
  for (const f of walk(path.join(root, dir)).filter(isSource)) {
    const t = fs.readFileSync(f, 'utf8');
    for (const m of t.matchAll(/export\s+(?:declare\s+)?(?:const|let|function|class|type|interface|enum)\s+(\w+)/g)) names.add(m[1]);
    for (const m of t.matchAll(/export\s+(?:type\s+)?\{([^}]*)\}/g)) m[1].split(',').forEach((n) => n.trim() && names.add(n.trim().split(/\s+as\s+/).pop()));
  }
  return names;
};
const known = { '@/domain': exportsOf('src/domain'), '@/state': exportsOf('src/state') };
const stateOnly = new Set([...known['@/state']].filter(Boolean));
for (const f of walk(path.join(root, 'src/state')).filter((x) => /\/state\/[^/]+\.ts$/.test(x.split(path.sep).join('/')))) void f;

const iconSrc = fs.readFileSync(path.join(root, 'src/icons/icon-data.ts'), 'utf8') + fs.readFileSync(path.join(root, 'src/icons/nav-icons.ts'), 'utf8');
const iconNames = new Set([...iconSrc.matchAll(/^\s{2}([A-Za-z_]\w*):\s*\[/gm)].map((m) => m[1]));

const resolves = (spec, fromFile) => {
  const base = spec.startsWith('@/') ? path.join(root, 'src', spec.slice(2)) : path.resolve(path.dirname(fromFile), spec);
  return ['.ts', '.tsx', '/index.ts', '/index.tsx', ''].some((ext) => fs.existsSync(base + ext) && fs.statSync(base + ext).isFile());
};

for (const f of ui) {
  const rel = path.relative(root, f);
  const t = fs.readFileSync(f, 'utf8');
  for (const m of t.matchAll(/import\s+(?:type\s+)?(?:[\w*\s,{}]+?)\s+from\s+'([^']+)'/g)) {
    const spec = m[1];
    if ((spec.startsWith('@/') || spec.startsWith('.')) && !resolves(spec, f)) problems.push(`${rel} : import introuvable « ${spec} »`);
  }
  for (const m of t.matchAll(/import\s+(?:type\s+)?\{([^}]*)\}\s+from\s+'(@\/(?:domain|state))'/g)) {
    const names = m[1].split(',').map((n) => n.trim().replace(/^type\s+/, '').split(/\s+as\s+/)[0]).filter(Boolean);
    for (const n of names) if (!known[m[2]].has(n)) problems.push(`${rel} : « ${n} » n'est pas exporté par ${m[2]}`);
  }
  for (const m of t.matchAll(/<Icon\s+[^>]*?name=(?:"([^"]+)"|\{'([^']+)'\})/g)) {
    const n = m[1] || m[2];
    if (!iconNames.has(n)) problems.push(`${rel} : icône inconnue « ${n} »`);
  }
  for (const m of t.matchAll(/icon:\s*'(\w+)'/g)) if (!iconNames.has(m[1])) problems.push(`${rel} : icône inconnue « ${m[1]} »`);
}

console.log(`${ui.length} fichiers UI contrôlés, ${iconNames.size} icônes connues.`);
if (problems.length) {
  console.error('\nPROBLÈMES :\n' + problems.map((p) => ' - ' + p).join('\n'));
  process.exit(1);
}
console.log('Aucun problème détecté (syntaxe, imports, symboles, icônes).');

text.scripts/generate-icons.cjs:
'use strict';
/**
 * Génère src/icons/icon-data.ts à partir des tables ICONS et HABIT_ICONS de la PWA
 * (legacy/js/core.js). Les fragments SVG sont analysés en nœuds typés ; la seule
 * transformation rencontrée (ellipse pivotée) est convertie en tracé pur.
 *
 * Usage : node scripts/generate-icons.cjs
 */
const fs = require('node:fs');
const path = require('node:path');
const { createLegacy } = require('../tests/legacy-harness.cjs');
const { buildDb } = require('../tests/fixtures.cjs');

const legacy = createLegacy({ now: new Date(2026, 9, 28, 14), db: buildDb() });
const tables = { ui: legacy.call('ICONS'), habit: legacy.call('HABIT_ICONS') };

const TAGS = new Set(['path', 'circle', 'rect', 'line', 'polyline', 'polygon', 'ellipse']);
const camel = (s) => s.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
const num = (n) => String(Math.round(n * 1000) / 1000);

function ellipseToPath(a) {
  const cx = parseFloat(a.cx), cy = parseFloat(a.cy), rx = parseFloat(a.rx), ry = parseFloat(a.ry);
  const m = /rotate\(\s*(-?[\d.]+)\s+(-?[\d.]+)\s+(-?[\d.]+)\s*\)/.exec(a.transform || '');
  const deg = m ? parseFloat(m[1]) : 0;
  const ox = m ? parseFloat(m[2]) : cx, oy = m ? parseFloat(m[3]) : cy;
  const t = (deg * Math.PI) / 180, cos = Math.cos(t), sin = Math.sin(t);
  const rot = (x, y) => [ox + (x - ox) * cos - (y - oy) * sin, oy + (x - ox) * sin + (y - oy) * cos];
  const [x1, y1] = rot(cx - rx, cy);
  const [x2, y2] = rot(cx + rx, cy);
  return `M${num(x1)} ${num(y1)}A${num(rx)} ${num(ry)} ${num(deg)} 1 0 ${num(x2)} ${num(y2)}A${num(rx)} ${num(ry)} ${num(deg)} 1 0 ${num(x1)} ${num(y1)}Z`;
}

function parse(markup) {
  const nodes = [];
  const re = /<(\w+)((?:\s+[\w-]+="[^"]*")*)\s*\/?>/g;
  let m;
  while ((m = re.exec(markup))) {
    const tag = m[1];
    if (!TAGS.has(tag)) throw new Error(`balise SVG inattendue : ${tag}`);
    const attrs = {};
    for (const a of m[2].matchAll(/([\w-]+)="([^"]*)"/g)) attrs[a[1]] = a[2];
    if (tag === 'ellipse' && attrs.transform) {
      nodes.push({ tag: 'path', attrs: { d: ellipseToPath(attrs), ...(attrs.fill ? { fill: attrs.fill } : {}), ...(attrs.stroke ? { stroke: attrs.stroke } : {}) } });
    } else {
      const out = {};
      for (const [k, v] of Object.entries(attrs)) out[camel(k)] = v;
      nodes.push({ tag, attrs: out });
    }
  }
  const stripped = markup.replace(re, '').trim();
  if (stripped) throw new Error(`fragment SVG non analysé : ${stripped.slice(0, 60)}`);
  return nodes;
}

const lit = (v) => JSON.stringify(v).replace(/"([a-zA-Z]+)":/g, '$1:').replace(/"/g, "'");
let out = `// FICHIER GÉNÉRÉ par scripts/generate-icons.cjs : ne pas modifier à la main.
// Source : tables ICONS et HABIT_ICONS de la PWA d'origine (legacy/js/core.js).

export type SvgTag = 'path' | 'circle' | 'rect' | 'line' | 'polyline' | 'polygon' | 'ellipse';

export interface IconNode {
  readonly tag: SvgTag;
  /** Attributs SVG en camelCase ; \`currentColor\` est remplacé par la couleur du composant. */
  readonly attrs: Readonly<Record<string, string>>;
}

`;
for (const [group, table] of Object.entries(tables)) {
  const name = group === 'ui' ? 'UI_ICONS' : 'HABIT_ICON_NODES';
  out += `export const ${name} = {\n`;
  for (const id of Object.keys(table).sort()) out += `  ${/^[a-z_]\w*$/i.test(id) ? id : `'${id}'`}: ${lit(parse(table[id]))},\n`;
  out += `} as const satisfies Record<string, readonly IconNode[]>;\n\n`;
}
out += `export type UiIconName = keyof typeof UI_ICONS;
export type HabitIconName = keyof typeof HABIT_ICON_NODES;
export type IconName = UiIconName | HabitIconName;

export const ICON_NODES: Readonly<Record<IconName, readonly IconNode[]>> = { ...UI_ICONS, ...HABIT_ICON_NODES };
`;
fs.writeFileSync(path.join(__dirname, '..', 'src/icons/icon-data.ts'), out);
const n = (o) => Object.keys(o).length;
console.log(`icon-data.ts : ${n(tables.ui)} icônes d'interface + ${n(tables.habit)} icônes d'habitudes`);

text.scripts/generate-sounds.cjs:
'use strict';
/**
 * Génère assets/sounds/*.wav à partir des formules de la PWA (Web Audio) :
 *  - effets : done, undo, fail, drink, fanfare, levelup (playSound) et bell (playBell) ;
 *  - ambiances en boucle : rain, ocean, drone (startAmbience).
 * Déterministe (PRNG à graine) : relancer le script donne exactement les mêmes fichiers.
 *
 * Usage : node scripts/generate-sounds.cjs
 */
const fs = require('node:fs');
const path = require('node:path');

const OUT = path.join(__dirname, '..', 'assets', 'sounds');
const TAU = Math.PI * 2;

// ─────────────── Outils ───────────────

function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function wave(type, phase) {
  const p = phase - Math.floor(phase);
  if (type === 'sine') return Math.sin(TAU * p);
  if (type === 'triangle') return (2 / Math.PI) * Math.asin(Math.sin(TAU * p));
  if (type === 'sawtooth') return 2 * (p - Math.floor(p + 0.5));
  throw new Error(`forme d'onde inconnue : ${type}`);
}

/** Note de playSound : `e(freq, dur, type, gain, floor)` — décroissance exponentielle de `gain` à `floor`. */
function addNote(buf, sr, start, freq, dur, type = 'sine', gain = 0.2, floor = 0.001) {
  const i0 = Math.round(start * sr);
  const n = Math.round(dur * sr);
  for (let i = 0; i < n && i0 + i < buf.length; i++) {
    const t = i / sr;
    buf[i0 + i] += wave(type, freq * t) * gain * Math.pow(floor / gain, t / dur);
  }
}

/** Partiel de cloche : 1e-4 → c·0,5 en 12 ms, puis décroissance exponentielle jusqu'à 1e-4 à `len` s. */
function addBellPartial(buf, sr, freq, amp, len) {
  const n = Math.round((len + 0.1) * sr);
  const peak = amp * 0.5;
  for (let i = 0; i < n && i < buf.length; i++) {
    const t = i / sr;
    let g;
    if (t < 0.012) g = 1e-4 * Math.pow(peak / 1e-4, t / 0.012);
    else if (t < len) g = peak * Math.pow(1e-4 / peak, (t - 0.012) / (len - 0.012));
    else g = 0;
    buf[i] += Math.sin(TAU * freq * t) * g;
  }
}

/** Filtre biquad RBJ identique à BiquadFilterNode (Q en dB pour passe-bas / passe-haut, Q = 1 par défaut). */
function biquad(type, freq, sr, qDb = 1) {
  const w0 = (TAU * freq) / sr;
  const alpha = Math.sin(w0) / (2 * Math.pow(10, qDb / 20));
  const cos = Math.cos(w0);
  let b0, b1, b2;
  if (type === 'lowpass') {
    b0 = (1 - cos) / 2;
    b1 = 1 - cos;
    b2 = (1 - cos) / 2;
  } else {
    b0 = (1 + cos) / 2;
    b1 = -(1 + cos);
    b2 = (1 + cos) / 2;
  }
  const a0 = 1 + alpha;
  const c = [b0 / a0, b1 / a0, b2 / a0, (-2 * cos) / a0, (1 - alpha) / a0];
  let x1 = 0, x2 = 0, y1 = 0, y2 = 0;
  return (x) => {
    const y = c[0] * x + c[1] * x1 + c[2] * x2 - c[3] * y1 - c[4] * y2;
    x2 = x1; x1 = x; y2 = y1; y1 = y;
    return y;
  };
}

function noise(kind, n, rand) {
  const out = new Float32Array(n);
  if (kind === 'brown') {
    let last = 0;
    for (let i = 0; i < n; i++) {
      const w = rand() * 2 - 1;
      last = (last + 0.02 * w) / 1.02;
      out[i] = last * 3.5;
    }
  } else {
    let b0 = 0, b1 = 0, b2 = 0, b3 = 0, b4 = 0, b5 = 0, b6 = 0;
    for (let i = 0; i < n; i++) {
      const w = rand() * 2 - 1;
      b0 = 0.99886 * b0 + w * 0.0555179;
      b1 = 0.99332 * b1 + w * 0.0750759;
      b2 = 0.969 * b2 + w * 0.153852;
      b3 = 0.8665 * b3 + w * 0.3104856;
      b4 = 0.55 * b4 + w * 0.5329522;
      b5 = -0.7616 * b5 - w * 0.016898;
      out[i] = (b0 + b1 + b2 + b3 + b4 + b5 + b6 + w * 0.5362) * 0.11;
      b6 = w * 0.115926;
    }
  }
  return out;
}

/** Boucle sans couture : on génère `fade` secondes de plus et on les mêle (fondu linéaire) au début. */
function makeLoop(render, sr, seconds, fadeSeconds) {
  const n = Math.round(seconds * sr);
  const f = Math.round(fadeSeconds * sr);
  const raw = render(n + f);
  const out = new Float32Array(n);
  for (let i = 0; i < n; i++) out[i] = raw[i];
  for (let i = 0; i < f; i++) {
    const k = i / f;
    out[i] = raw[i] * k + raw[n + i] * (1 - k);
  }
  return out;
}

function toWav(samples, sr) {
  const data = Buffer.alloc(samples.length * 2);
  for (let i = 0; i < samples.length; i++) {
    const s = Math.max(-1, Math.min(1, samples[i]));
    data.writeInt16LE(Math.round(s * 32767), i * 2);
  }
  const head = Buffer.alloc(44);
  head.write('RIFF', 0);
  head.writeUInt32LE(36 + data.length, 4);
  head.write('WAVEfmt ', 8);
  head.writeUInt32LE(16, 16);
  head.writeUInt16LE(1, 20);
  head.writeUInt16LE(1, 22);
  head.writeUInt32LE(sr, 24);
  head.writeUInt32LE(sr * 2, 28);
  head.writeUInt16LE(2, 32);
  head.writeUInt16LE(16, 34);
  head.write('data', 36);
  head.writeUInt32LE(data.length, 40);
  return Buffer.concat([head, data]);
}

// ─────────────── Effets (playSound / playBell) ───────────────

const FX_SR = 44100;
const effect = (seconds, fn) => {
  const buf = new Float32Array(Math.round(seconds * FX_SR));
  fn(buf);
  return buf;
};

const EFFECTS = {
  done: effect(0.3, (b) => {
    addNote(b, FX_SR, 0, 659, 0.05);
    addNote(b, FX_SR, 0.05, 880, 0.2);
  }),
  undo: effect(0.35, (b) => {
    addNote(b, FX_SR, 0, 440, 0.15);
    addNote(b, FX_SR, 0.08, 330, 0.2);
  }),
  fail: effect(0.4, (b) => addNote(b, FX_SR, 0, 280, 0.35, 'sawtooth', 0.18)),
  drink: effect(0.45, (b) => [523, 659].forEach((f, i) => addNote(b, FX_SR, i * 0.1, f, 0.3))),
  fanfare: effect(1, (b) => [523, 659, 784, 1047].forEach((f, i) => addNote(b, FX_SR, i * 0.13, f, 0.5, 'triangle', 0.22))),
  levelup: effect(1.05, (b) => [523, 659, 784, 1047, 1319].forEach((f, i) => addNote(b, FX_SR, i * 0.1, f, 0.55, 'sine', 0.28))),
  bell: effect(7.3, (b) => {
    const base = 196;
    [[1, 0.55, 7], [2.76, 0.28, 4.5], [5.4, 0.14, 3], [8.93, 0.07, 2]].forEach(([u, c, len]) => addBellPartial(b, FX_SR, base * u, c, len));
  }),
};

// ─────────────── Ambiances (startAmbience) ───────────────

const AMB_SR = 22050;

const AMBIENCES = {
  // Bruit rose → passe-haut 900 Hz → passe-bas 7 kHz → gain 0,5.
  rain: makeLoop(
    (n) => {
      const src = noise('pink', n, rng(1001));
      const hp = biquad('highpass', 900, AMB_SR);
      const lp = biquad('lowpass', 7000, AMB_SR);
      return src.map((x) => lp(hp(x)) * 0.5);
    },
    AMB_SR, 20, 2,
  ),
  // Bruit brun → passe-bas 650 Hz → gain 0,45 modulé par un LFO de 0,09 Hz (amplitude 0,35).
  // 3 périodes du LFO = 33,33 s : la modulation boucle sans saut.
  ocean: makeLoop(
    (n) => {
      const src = noise('brown', n, rng(2002));
      const lp = biquad('lowpass', 650, AMB_SR);
      return src.map((x, i) => lp(x) * (0.45 + 0.35 * Math.sin(TAU * 0.09 * (i / AMB_SR))));
    },
    AMB_SR, 3 / 0.09, 3,
  ),
  // 4 sinus (110 / 164,81 / 220 / 329,63 Hz, désaccordés de 0/3/−3/2 cents) → gain 0,9 modulé à 0,07 Hz (± 0,12).
  // 2 périodes du LFO = 28,57 s.
  drone: makeLoop(
    (n) => {
      const out = new Float32Array(n);
      const partials = [[110, 0.1, 0], [164.81, 0.07, 3], [220, 0.06, -3], [329.63, 0.025, 2]];
      for (let i = 0; i < n; i++) {
        const t = i / AMB_SR;
        let sum = 0;
        for (const [f, g, cents] of partials) sum += Math.sin(TAU * f * Math.pow(2, cents / 1200) * t) * g;
        out[i] = sum * (0.9 + 0.12 * Math.sin(TAU * 0.07 * t));
      }
      return out;
    },
    AMB_SR, 2 / 0.07, 3,
  ),
};

// ─────────────── Écriture ───────────────

fs.mkdirSync(OUT, { recursive: true });
let total = 0;
const write = (name, samples, sr) => {
  let peak = 0;
  let sum = 0;
  for (const s of samples) {
    peak = Math.max(peak, Math.abs(s));
    sum += s * s;
  }
  const wav = toWav(samples, sr);
  fs.writeFileSync(path.join(OUT, `${name}.wav`), wav);
  total += wav.length;
  console.log(`${name.padEnd(8)} ${(samples.length / sr).toFixed(2).padStart(6)} s  ${String(sr).padStart(5)} Hz  crête ${peak.toFixed(3)}  rms ${Math.sqrt(sum / samples.length).toFixed(3)}  ${(wav.length / 1024).toFixed(0)} Ko`);
};
for (const [name, s] of Object.entries(EFFECTS)) write(name, s, FX_SR);
for (const [name, s] of Object.entries(AMBIENCES)) write(name, s, AMB_SR);
console.log(`total ${(total / 1024 / 1024).toFixed(2)} Mo`);

text.scripts/install-deps.cjs:
'use strict';
/**
 * Installe toutes les dépendances Expo / React Native du projet en une seule commande,
 * identique sous Windows (cmd, PowerShell), macOS et Linux.
 * Usage : npm run install:deps
 *
 * `npx expo install` peut se terminer sur une erreur ERR_MODULE_NOT_FOUND (…autoAddConfigPlugins.js)
 * APRÈS avoir installé les paquets : c'est l'étape annexe d'ajout automatique des plugins dans
 * app.json (déjà déclarés à la main ici). On ne s'arrête donc pas dessus : on vérifie les paquets.
 */
const { spawnSync } = require('node:child_process');
const fs = require('node:fs');
const path = require('node:path');

const RUNTIME = [
  'expo-router', 'react', 'react-dom', 'react-native', 'react-native-web',
  'react-native-svg', 'react-native-safe-area-context', 'react-native-screens',
  'expo-linking', 'expo-constants', 'expo-status-bar', 'expo-font', 'expo-splash-screen',
  'expo-asset', // requis par expo-audio
  'expo-haptics', 'expo-audio', 'expo-keep-awake', 'expo-clipboard', 'expo-notifications',
  'expo-document-picker', 'expo-sharing', 'expo-file-system',
  '@react-native-async-storage/async-storage',
];

const run = (args, { soft = false } = {}) => {
  console.log(`\n> ${args.join(' ')}\n`);
  const r = spawnSync(args[0], args.slice(1), { stdio: 'inherit', shell: true });
  if (r.status !== 0 && !soft) {
    console.error(`\nÉchec de : ${args.join(' ')}`);
    process.exit(r.status ?? 1);
  }
  return r.status === 0;
};

const missing = () => RUNTIME.filter((p) => !fs.existsSync(path.join(process.cwd(), 'node_modules', ...p.split('/'), 'package.json')));

run(['npm', 'install', 'expo@latest']);
const ok = run(['npx', 'expo', 'install', ...RUNTIME], { soft: true });
let absent = missing();

if (!ok) {
  console.warn(
    '\n⚠ « expo install » a signalé une erreur. Si elle mentionne ERR_MODULE_NOT_FOUND / autoAddConfigPlugins.js,\n' +
      '  elle est sans gravité (étape finale d\'ajout de plugins, déjà déclarés dans app.json).',
  );
  if (absent.length > 0) {
    console.warn(`  Paquets absents, nouvelle tentative avec npm : ${absent.join(', ')}`);
    run(['npm', 'install', ...absent], { soft: true });
    absent = missing();
  }
}

run(['npm', 'install', '-D', '@types/react'], { soft: true });

if (absent.length > 0) {
  console.error(`\n✖ Paquets toujours absents : ${absent.join(', ')}\n  Installe-les un par un : npx expo install <paquet>`);
  process.exit(1);
}
console.log('\n✔ Tous les paquets sont présents. Vérification de la cohérence des versions :');
run(['npx', 'expo-doctor'], { soft: true });
console.log('\nEnsuite : npm run typecheck   puis   npx expo start');
console.log('N\'exécute PAS « npm audit fix --force » : il rétrograderait Expo vers une très ancienne version.');

