export function RichLine({ parts, variant = 'body' }: { readonly parts: readonly RichText[]; readonly variant?: 'body' | 'caption' }) {
  return (
    <AppText variant={variant}>
      {parts.map((p, i) =>
        p.bold ? (
          <AppText key={i} variant="bodyStrong">
            {p.text}
          </AppText>
        ) : (
          p.text
        ),
      )}
    </AppText>
