    { id: 'nodays', title: 'nodays', body: '', hour: 9, minute: 0, days: [], habitId: '', enabled: true },
    ...Array.from({ length: 30 }, (_, i) => ({ id: `m${i}`, title: `m${i}`, body: '', hour: 15 + (i % 8), minute: i, days: [0, 1, 2, 3, 4, 5, 6], habitId: '', enabled: true })),
  ];
